input.command:
node -e "
const fs = require('fs');
const https = require('https');
const http = require('http');

// Read the .env.test file
const envContent = fs.readFileSync('.env.test', 'utf8');

// Parse environment variables
const envVars = {};
envContent.split('\n').forEach(line => {
  // Skip comments and empty lines
  if (line.trim() && !line.startsWith('#')) {
    const [key, ...valueParts] = line.split('=');
    if (key && valueParts.length > 0) {
      const value = valueParts.join('=').trim();
      envVars[key.trim()] = value;
    }
  }
});

console.log('Parsed environment variables:');
console.log(JSON.stringify(envVars, null, 2));

// POST to the API
const postData = JSON.stringify(envVars);
const options = {
  hostname: 'localhost',
  port: 3003,
  path: '/api/doc-export',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(postData)
  }
};

console.log('\nSending POST request to http://localhost:3003/api/doc-export...');

const req = http.request(options, (res) => {
  console.log(\`Status: \${res.statusCode}\`);
  console.log(\`Headers: \${JSON.stringify(res.headers, null, 2)}\`);

  let responseBody = '';
  res.on('data', (chunk) => {
    responseBody += chunk;
  });

  res.on('end', () => {
    console.log('\nResponse body:');
    console.log(responseBody);
  });
});

req.on('error', (e) => {
  console.error(\`Request failed: \${e.message}\`);
  console.error('Note: Make sure the server at http://localhost:3003 is running.');
});

req.write(postData);
req.end();
"

